function go(screen,reset=false){if(screen===S.screen)return;if(reset)S.stack=[];else S.stack.push(S.screen);S.screen=screen;S.modal=null;render();}
function back(){S.modal?S.modal=null:(S.screen=S.stack.pop()||'home');render();}
function tabbar(){return `<nav class="bottom-nav" aria-label="主导航">${[['home','home','学习'],['library','books','题库'],['review','review','复习'],['stats','chart','统计']].map(([id,ic,tx])=>`<button class="tab ${S.screen===id?'active':''}" data-route="${id}" data-reset="1"><span class="tab-icon">${icon(ic,21)}</span>${tx}</button>`).join('')}</nav>`}
function header(){let sub=S.screen==='home'?'一个小目标，一点点进步':'';return `<header class="app-header">${!primaryScreens.includes(S.screen)?`<button class="icon-btn back-btn" aria-label="返回" data-action="back">${icon('arrow',21)}</button>`:''}<div class="header-title">${esc(screenTitles[S.screen]||'知序')}${sub?`<span class="header-sub">${sub}</span>`:''}</div>${S.screen==='home'?`<button class="icon-btn" aria-label="搜索题库" data-route="library">${icon('search')}</button><button class="icon-btn" aria-label="设置" data-route="settings">${icon('settings')}</button>`:''}${S.screen==='library'?`<button class="icon-btn" data-route="import_source" aria-label="导入">${icon('upload')}</button><button class="icon-btn" data-action="libraryMenu" aria-label="题库菜单">${icon('more')}</button>`:''}${S.screen==='quiz'?`<button class="icon-btn" data-action="answerSheet" aria-label="答题卡">${icon('list')}</button><button class="icon-btn" data-action="bookmark" aria-label="收藏">${icon('bookmark')}</button>`:''}</header>`}
function card(content,cls='',extra=''){return `<div class="card ${cls}" ${extra}>${content}</div>`}
function title(t,action='',label='查看全部'){return `<div class="section-head"><h2>${t}</h2>${action?`<button class="link" data-route="${action}">${label} ${icon('right',12)}</button>`:''}</div>`}
function progress(value){return `<div class="progress-track"><div class="progress-fill" style="width:${Math.max(0,Math.min(100,value))}%"></div></div>`}
function iconBtn(ic,action){return `<button class="icon-btn" data-action="${action}">${icon(ic)}</button>`}
function toggle(label,desc,id,value){return `<div class="toggle-row" data-action="toggle" data-key="${id}"><div class="grow"><div class="semi">${label}</div>${desc?`<div class="section-caption">${desc}</div>`:''}</div><button type="button" class="switch ${value?'on':''}" role="switch" aria-checked="${!!value}" aria-label="${label}"><span></span></button></div>`}
function selectField(label,id,opts,value,hint=''){return `<div class="field"><label for="${id}">${label}</label><select id="${id}" data-bind="${id}">${opts.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select>${hint?`<div class="hint">${hint}</div>`:''}</div>`}
function inputField(label,id,value='',placeholder='',hint=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" data-bind="${id}" value="${esc(value)}" placeholder="${esc(placeholder)}"/>${hint?`<div class="hint">${hint}</div>`:''}</div>`}
function rowBook(b){let pct=b.count?Math.round((b.completed/b.count)*100):0;return card(`<div class="library-row"><div class="book-icon ${b.color}">${icon('books',23)}</div><div class="grow"><div class="semi overflow">${esc(b.name)}</div><div class="muted tiny" style="margin:5px 0 9px">${esc(b.desc)}</div>${progress(pct)}</div>${icon('right',16)}</div><div class="row between" style="margin:11px 2px 0"><span class="tiny muted">${b.count} 题 · 已练 ${b.completed}</span><span class="tiny muted">${pct}%</span></div>`,'clickable',`data-action="openBook" data-name="${esc(b.name)}"`)}
function qtags(q){return `${chip(q.type)} ${chip(q.difficulty)} ${chip(q.chapter)}`}
function getBookQuestions(){return S.questions.filter(x=>x.book===S.activeBook)}
function initQuiz(){const book=S.quiz.book||S.activeBook;let items=S.questions.filter(q=>q.book===book);if(S.quiz.range==='错题')items=items.filter(q=>q.wrong>0);if(S.quiz.range==='收藏')items=items.filter(q=>q.star);if(S.quiz.mode==='随机练习'||S.settings.shuffle)items=[...items].sort(()=>Math.random()-.5);S.quiz.ids=items.slice(0,+S.quiz.qty||10).map(q=>q.id);if(!S.quiz.ids.length)S.quiz.ids=S.questions.slice(0,3).map(q=>q.id);S.quiz.index=0;S.quiz.selected=[];S.quiz.submitted=false;S.quiz.results=[];go('quiz')}
function currentQ(){return S.questions.find(q=>q.id===S.quiz.ids[S.quiz.index])||S.questions[0]}
function homeScreen(){return `<main class="scroll with-bottom">
 <div class="row between" style="margin:7px 1px 12px"><span class="small muted">星期三 · 今日学习</span>${chip('连续学习 5 天','success')}</div>
 <div class="hero"><div class="hero-text"><div class="eyebrow">YOUR STUDY SPACE</div><h2>每天一点，<br>积少成多。</h2><p>把复杂的知识，变成清晰的进步。</p><button class="btn primary sm" data-route="practice_config">继续学习 ${icon('right',15)}</button></div>${illustration()}</div>
 ${title('今日计划','review_plan','调整计划')}
 ${card(`<div class="row between"><div><div class="muted tiny">今日已完成</div><div style="font-size:27px;font-weight:820;margin:6px 0">12 <span class="small muted">/ ${S.planTarget} 题</span></div></div><div style="color:#777bcb">${icon('target',31)}</div></div>${progress(Math.min(100,12/S.planTarget*100))}<div class="muted tiny" style="margin-top:10px">待复习 8 题 · 还有一点点就完成今日目标</div>`)}
 ${title('快速开始')}
 <div class="tile-grid"><button class="mini-tile" data-route="practice_config"><span class="symbol">${icon('graduation',19)}</span><div><div class="main">开始刷题</div><div class="sub">顺序 / 随机 / 章节</div></div></button><button class="mini-tile" data-route="review"><span class="symbol" style="background:#ffece4;color:#ae7858">${icon('review',19)}</span><div><div class="main">错题复习</div><div class="sub">8 道今日待复习</div></div></button><button class="mini-tile" data-route="import_source"><span class="symbol" style="background:#e7f2e9;color:#67917a">${icon('upload',19)}</span><div><div class="main">导入题库</div><div class="sub">智能识别多种格式</div></div></button><button class="mini-tile" data-route="history"><span class="symbol" style="background:#f8e9e8;color:#aa7b7b">${icon('clock',19)}</span><div><div class="main">历史记录</div><div class="sub">继续未完成的练习</div></div></button></div>
 ${title('最近使用','library')}
 ${rowBook(S.books[0])}
 </main>${tabbar()}`}
function libraryScreen(){const filtered=S.books.filter(b=>!S.search||b.name.includes(S.search)||b.desc.includes(S.search));return `<main class="scroll with-bottom"><div class="searchbar">${icon('search',19)}<input id="bookSearch" placeholder="搜索题库、章节和标签" value="${esc(S.search)}" aria-label="搜索题库"/><button data-action="searchBooks" class="link">搜索</button></div><div class="row between" style="margin:4px 1px 12px">${chip(`${S.books.length} 个题库`)}<button class="link" data-route="data">导出与备份</button></div>${filtered.map(rowBook).join('')||`<div class="empty-state">${illustration('empty')}<h3>还没有符合条件的题库</h3><p>换个关键词，或者导入新的题库。</p></div>`}<div class="space14"></div><div class="notice">${icon('info',17)}<span>可以从 Excel、CSV、TXT、JSON 等来源导入题目；导入前会进行字段核对与重复题检查。</span></div></main><button class="fab" data-route="import_source">${icon('plus',20)} 导入 / 新建</button>${tabbar()}`}
function bookDetailScreen(){const b=S.books.find(x=>x.name===S.activeBook)||S.books[0];const q=getBookQuestions();return `<main class="scroll"><div class="card soft"><div class="row start"><div class="book-icon lilac" style="background:white">${icon('books',25)}</div><div class="grow"><div class="lead">${esc(b.name)}</div><p class="small muted" style="line-height:1.7">${esc(b.desc)}</p></div></div><div class="row between"><span class="small">总题量 <b>${b.count}</b></span><span class="small">已练 <b>${b.completed}</b></span><span class="small">进度 <b>${Math.round(b.completed/b.count*100)}%</b></span></div><div class="space8"></div>${progress(b.completed/b.count*100)}</div>
 <div class="tile-grid section-space"><button class="btn primary" data-route="practice_config">${icon('graduation',18)}开始练习</button><button class="btn secondary" data-route="questions">${icon('list',18)}查看题目</button></div>
 ${title('章节概况')}
 ${[...new Set(q.map(x=>x.chapter))].map(ch=>`<div class="list-item" data-action="chapter" data-chapter="${esc(ch)}"><div class="support-icon">${icon('layers',18)}</div><div class="grow"><div class="semi">${esc(ch)}</div><div class="tiny muted">${q.filter(x=>x.chapter===ch).length} 条已加载演示题目</div></div>${icon('right',17)}</div>`).join('')}
 ${title('题库工具')}
 <div class="list-simple"><div class="list-item" data-route="import_source">${icon('upload',20)}<span class="grow">追加导入 / 更新题库</span>${icon('right',17)}</div><div class="list-item" data-route="questions">${icon('pencil',20)}<span class="grow">编辑和批量审查题目</span>${icon('right',17)}</div><div class="list-item" data-route="audit">${icon('duplicate',20)}<span class="grow">全库重复与答案冲突检查</span>${icon('right',17)}</div><div class="list-item" data-action="bookMenu">${icon('more',20)}<span class="grow">重命名 / 导出 / 删除</span>${icon('right',17)}</div></div></main>`}
function questionsScreen(){let items=getBookQuestions();if(S.filter==='错题')items=items.filter(x=>x.wrong>0);if(S.filter==='收藏')items=items.filter(x=>x.star);if(S.filter==='困难')items=items.filter(x=>x.difficulty==='困难');if(S.search)items=items.filter(x=>[x.text,x.chapter,x.explanation].join('|').includes(S.search));return `<main class="scroll"><div class="searchbar">${icon('search',18)}<input id="questionSearch" value="${esc(S.search)}" placeholder="搜索题干 / 解析 / 章节"/><button class="link" data-action="searchQuestions">查找</button></div><div class="tabs-inline">${['全部','错题','收藏','困难'].map(f=>`<button class="${S.filter===f?'active':''}" data-action="filterQuestions" data-value="${f}">${f}</button>`).join('')}</div>${card(`<div class="row between"><div class="small muted">${items.length} 道匹配题目</div><div class="row"><button class="btn sm tonal" data-action="addQuestion">${icon('plus',15)}添加</button><button class="btn sm outline" data-route="import_source">${icon('upload',15)}导入</button></div></div>`)}<div class="space8"></div>${items.map((q,i)=>card(`<div class="q-index"><span class="small muted">#${q.id}</span>${chip(q.type)}${chip(q.difficulty)}</div><div class="q-text">${esc(q.text)}</div><div class="row between"><div class="tiny muted">${esc(q.chapter)} · ${q.options.length} 个选项</div><button class="link" data-action="editQuestion" data-id="${q.id}">编辑 ${icon('right',12)}</button></div>`)).join('')||`<div class="empty-state"><h3>没有符合条件的题目</h3><p>清除筛选后重试。</p></div>`}</main>`}
function editorScreen(){const q=S.editId?S.questions.find(x=>x.id===S.editId):null;return `<main class="scroll"><div class="notice">${icon('pencil',18)}<span>支持编辑题型、答案、选项、解析和难度。保存后原始学习记录不会被直接覆盖。</span></div>${selectField('题型','edit_type',['单选题','多选题','判断题','不定项选择题','填空题','简答题'],q?.type||'单选题')}
 <div class="field"><label>题干 *</label><textarea data-bind="edit_text" placeholder="输入题目内容">${esc(q?.text||'')}</textarea></div>
 ${['A','B','C','D'].map((letter,i)=>inputField(`选项 ${letter}`,`edit_opt${i}`,q?.options?.[i]||'',`选项 ${letter} 内容`)).join('')}
 ${inputField('正确答案','edit_answer',q?.answer?.join(',')||'A','例如：A 或 A,B,C','支持单选/多选；判断题使用 A=正确、B=错误')}
 <div class="field"><label>解析</label><textarea data-bind="edit_explanation" placeholder="为什么这个答案正确？">${esc(q?.explanation||'')}</textarea></div>
 ${selectField('难度','edit_difficulty',['简单','中等','困难','未标注'],q?.difficulty||'中等')}${inputField('章节 / 知识点','edit_chapter',q?.chapter||'','例如：列车运行图')}
 <button class="btn primary full" data-action="saveQuestion">${icon('check',18)}保存题目</button><div class="space14"></div></main>`}
function reviewScreen(){const count=S.questions.filter(x=>x.wrong>0).length;return `<main class="scroll"><div class="hero" style="min-height:132px;background:linear-gradient(120deg,#f9e9e4,#f1eefa)"><div class="hero-text"><div class="eyebrow">REVIEW ROUTINE</div><h2 style="font-size:20px">温故，而知新。</h2><p>今天有 8 道题等待回顾</p><button class="btn sm primary" data-route="review_plan">查看复习计划</button></div><div style="position:absolute;right:-25px;top:19px;transform:scale(.6)">${illustration('empty')}</div></div>
 ${title('我的复习库')}
 <div class="tabs-inline">${['待复习','错题','收藏','疑难'].map(s=>`<button data-action="reviewTab" data-value="${s}" class="${S.reviewTab===s?'active':''}">${s}</button>`).join('')}</div>
 <div class="tile-grid"><div class="stat-tile"><div class="muted small">错题总数</div><div class="stat-val">${count}</div></div><div class="stat-tile"><div class="muted small">收藏题目</div><div class="stat-val">${S.questions.filter(q=>q.star).length}</div></div></div>
 ${title(S.reviewTab==='待复习'?'今日推荐题目':`${S.reviewTab}题目`)}
 ${S.questions.filter(q=>S.reviewTab==='收藏'?q.star:S.reviewTab==='疑难'?q.difficulty==='困难':q.wrong>0).slice(0,5).map(q=>card(`<div class="row between"><div class="small muted">${esc(q.chapter)}</div>${chip(S.reviewTab==='待复习'?'建议今日复习':q.difficulty,S.reviewTab==='待复习'?'warn':'')}</div><div class="q-text" style="margin:9px 0">${esc(q.text)}</div><div class="row between"><div class="tiny muted">${q.wrong} 次错误 · ${q.type}</div><button class="link" data-action="practiceOne" data-id="${q.id}">练习 ${icon('right',13)}</button></div>`)).join('')}
 <div class="space14"></div><button class="btn primary full" data-action="startReview">${icon('review',18)}开始错题复习</button></main>${tabbar()}`}
function statsScreen(){return `<main class="scroll"><div class="tabs-inline">${['近7天','近30天','全部'].map(v=>`<button data-action="statsRange" data-value="${v}" class="${S.tabStat===v?'active':''}">${v}</button>`).join('')}</div><div class="tile-grid"><div class="stat-tile"><div class="muted small">练习题目</div><div class="stat-val">${S.tabStat==='近7天'?'126':S.tabStat==='近30天'?'472':'1,280'}</div><span class="tiny muted">本周期完成</span></div><div class="stat-tile"><div class="muted small">首次正确率</div><div class="stat-val">78<span class="small">%</span></div><span class="tiny muted">比上周期 +6%</span></div><div class="stat-tile"><div class="muted small">累计学习</div><div class="stat-val">18.5<span class="small">h</span></div><span class="tiny muted">专注练习时间</span></div><div class="stat-tile"><div class="muted small">连续学习</div><div class="stat-val">5<span class="small">天</span></div><span class="tiny muted">保持良好节奏</span></div></div>
 ${title('每日练习量')}${card(`<div class="muted tiny">练习题数（示例统计）</div><div class="bar-chart">${[48,68,44,79,93,64,85].map((x,i)=>`<div class="chart-item"><div class="chart-bar ${i===6?'highlight':''}" style="height:${x}%"></div><span class="chart-label">${['四','五','六','日','一','二','三'][i]}</span></div>`).join('')}</div>`)}
 ${title('薄弱知识点')}${card([['列车运行图',64],['区间通过能力',52],['车站接发列车',83]].map(([label,rate])=>`<div style="margin:9px 0 16px"><div class="row between small" style="margin-bottom:8px"><span>${label}</span><span class="muted">${rate}% 掌握度</span></div>${progress(rate)}</div>`).join(''))}
 ${title('更多记录')}<div class="list-item" data-route="history">${icon('clock',20)}<div class="grow">查看练习历史</div>${icon('right',17)}</div></main>${tabbar()}`}
function importSteps(active){return `<div class="row between"><span class="stepper-note">第 ${active} / 4 步</span><span class="stepper-note">${['选择文件','识别与映射','审查与去重','导入结果'][active-1]}</span></div><div class="stepper">${[1,2,3,4].map(i=>`<div class="segment ${i<=active?'on':''}"></div>`).join('')}</div>`}
const supportedFormats=[['XLSX','Excel 新版'],['XLS','Excel 旧版'],['CSV','表格文本'],['TSV','制表符'],['JSON','结构化'],['TXT','纯文本'],['DOCX','Word 文档'],['PDF','PDF 文档']];
function sourceScreen(){let i=S.imports;return `<main class="scroll">${importSteps(1)}<div class="card soft"><div class="row start"><div class="support-icon">${icon('spark',22)}</div><div class="grow"><div class="lead">智能导入题库</div><div class="section-caption" style="margin-top:5px">识别字段、核对答案、检查重复后再写入。默认不自动覆盖旧题。</div></div></div></div>
 ${title('选择文件')}
 <input type="file" id="fileChooser" accept=".xlsx,.xls,.csv,.tsv,.json,.txt,.docx,.pdf" hidden/>
 <div class="card clickable" style="text-align:center;border:1.5px dashed #b4b6e2;padding:22px" data-action="pickFile"><div class="illustration-inline" style="color:var(--primary)">${icon('upload',35)}</div><div style="font-weight:750;margin:10px 0 4px">${i.fromFile?esc(i.name):'点击选择本地文件'}</div><div class="muted tiny">使用 Android 系统文件选择器的交互示意</div><div class="space8"></div>${chip(i.fromFile?'已选择文件':'支持多种文档与表格')}</div>
 <div class="space8"></div><div class="row" style="gap:7px"><button class="btn tonal grow sm" data-action="useDemo">${icon('file',16)}使用演示 Excel</button><button class="btn outline grow sm" data-action="pasteText">${icon('pencil',16)}粘贴文本</button></div>
 ${title('可导入类型')}
 <div class="chips">${supportedFormats.map(([f,desc])=>`<span class="chip">${f} <span style="opacity:.65">· ${desc}</span></span>`).join('')}</div>
 <div class="notice warn">${icon('info',18)}<span><b>原型说明：</b>CSV / TSV / JSON / TXT 可在此原型尝试本地解析；XLSX / XLS / DOCX / PDF 当前仅展示交互流程，使用示例题模拟识别。实际 Android 应用将使用 Kotlin 解析器。</span></div>
 ${S.importLog.some(l=>l.name===i.name)?`<div class="notice warn">${icon('duplicate',18)}<span>检测到本次会话曾导入同名文件。建议在后续步骤重点审查重复题和答案冲突。</span></div>`:''}
 ${title('导入位置')}${selectField('目标题库','imp_target',S.books.map(x=>x.name).concat('新建题库…'),i.target,'可以追加到已有题库，并保留原有学习记录')}
 ${card(`<div class="row between"><div><b class="small">识别前进行预处理</b><div class="section-caption">自动检测标题行、答案列、空行与工作表</div></div><span class="chip success">已启用</span></div>`)}
 </main><div class="sticky-action"><button class="btn primary full" data-action="startImport">开始智能识别 ${icon('right',19)}</button></div>`}
function fieldOptions(){return ['题目内容','题目类型','选项A~D','参考答案','解析说明','难度等级','所属章节','题干','正确答案','题型','解析','章节','选项A','选项B','选项C','选项D','不使用',...(S.imports.columns||[])].filter((x,i,a)=>a.indexOf(x)===i)}
function mappingScreen(){let i=S.imports;return `<main class="scroll">${importSteps(2)}
 ${card(`<div class="row start"><div class="support-icon">${icon('file',21)}</div><div class="grow"><div class="semi">${esc(i.name)}</div><div class="section-caption">${i.kind} · ${i.real?'本地读取成功':'演示数据'} · ${i.rawRows?.length||8} 行待审查</div></div>${chip(i.real?'已读取':'演示','success')}</div>`)}
 ${title('自动检测结果')}<div class="chips">${chip('检测到表头','success')}${chip('题干 98%','success')}${chip('答案 95%','success')}${chip('难度 82%','warn')}</div>
 <div class="value-row">${selectField('工作表','imp_sheet',['试题','答案说明','全部工作表'],i.sheet)}${inputField('起始数据行','imp_startRow',i.startRow,'2')}</div>
 ${title('字段映射')}<div class="section-caption">左侧为应用标准字段，右侧为文件中的列名。可手动修改；真实文本文件会根据这里的映射重新构建题目。</div>
 ${card(Object.entries({text:'题干 *',type:'题型',options:'选项 A–D',answer:'正确答案 *',explanation:'答案解析',difficulty:'难度',chapter:'章节'}).map(([key,label])=>`<div class="material-line" style="padding:7px 0;gap:8px"><div class="small" style="width:86px;flex-shrink:0">${label}</div><select style="flex:1;min-width:0;border:1px solid #e0e2ed;border-radius:10px;background:#f8f8fc;padding:10px 7px;font-size:11px;color:#53586d" data-bind="column_${key}">${fieldOptions().map(x=>`<option ${i.columnMap[key]===x?'selected':''}>${esc(x)}</option>`).join('')}</select>${icon('check',14)}</div>`).join(''))}
 ${title('预处理规则')}<div class="card">
 ${toggle('去除题号','识别“1.”“第 2 题”等前缀','removeSerial',i.rules.removeSerial)}
 ${toggle('答案标准化','兼容 A、ACD、A,C、1/2 等写法','normalizeAnswer',i.rules.normalizeAnswer)}
 ${toggle('自动推断题型','结合选项数量和答案数量辅助判断','inferType',i.rules.inferType)}
 ${toggle('合并换行选项','尝试识别同一单元格内的 A/B/C/D','mergeLines',i.rules.mergeLines)}
 ${toggle('跳过空白行','不把完全空白的表格行当成题目','skipEmpty',i.rules.skipEmpty)}
 </div>
 ${title('自定义识别规则')}<div class="card">
 ${inputField('去除题号的正则表达式','imp_customRegex',i.customRegex,'^第?\\d+[.、]','应用前须先校验表达式；不修改原始文件')}
 ${inputField('多选答案分隔规则','imp_answerDelimiter',i.answerDelimiter,'[,，、;；/\\s]+')}
 ${selectField('规则预设','imp_preset',i.presets,i.preset)}
 <button class="btn tonal full sm" data-action="savePreset">${icon('plus',16)}将当前规则保存为新预设</button>
 <div class="mode-banner">规则冲突、答案不在选项范围内、疑似重复题会进入人工审查，而不是自动放行。</div></div>
 </main><div class="sticky-action"><button class="btn outline grow" data-action="back">上一步</button><button class="btn primary grow" data-action="buildPreview">生成预览 ${icon('right',18)}</button></div>`}
function normalizedText(t){return String(t||'').replace(/[\s\u3000,.，。!?！？:：;；()（）\-]+/g,'').toLowerCase()}
function rowProblems(q){const err=[];if(!q.text?.trim())err.push('题干缺失');if(!q.answer?.length)err.push('答案缺失');if(!q.options?.length)err.push('选项缺失');const allowed=q.options.map((_,n)=>'ABCDEFGHIJKLMNOPQRSTUVWXYZ'[n]);if((q.answer||[]).some(a=>!allowed.includes(a)))err.push('答案指向不存在的选项');if(!['单选题','多选题','判断题','不定项选择题'].includes(q.type))err.push('题型未识别');if(q.type==='单选题'&&q.answer.length!==1)err.push('单选题答案数量异常');if(q.type==='判断题'&&q.options.length!==2)err.push('判断题选项数量异常');return err}
function rowStatus(row){const errors=rowProblems(row);if(errors.length)return {kind:'invalid',label:'待修正',details:errors.join('、')};const match=S.questions.find(q=>q.book===S.imports.target&&normalizedText(q.text)===normalizedText(row.text));if(match){const sameOptions=JSON.stringify(qSortText(match.options))===JSON.stringify(qSortText(row.options));const sameAnswer=[...match.answer].sort().join('')===[...row.answer].sort().join('');return {kind:sameOptions&&sameAnswer?'duplicate':'conflict',label:sameOptions&&sameAnswer?'完全重复':'内容冲突',details:match.id,existing:match}}
 return {kind:'ok',label:'识别通过',details:''}}
function qSortText(a){return (a||[]).map(x=>normalizedText(x))}
function counts(rows=S.imports.rows){const out={all:rows.length,ok:0,duplicate:0,conflict:0,invalid:0};rows.forEach(r=>out[rowStatus(r).kind]++);return out}
function previewScreen(){const i=S.imports,c=counts();const filtered=i.rows.filter(q=>i.previewFilter==='全部'||i.previewFilter==='待修正'&&rowStatus(q).kind==='invalid'||i.previewFilter==='重复/冲突'&&['duplicate','conflict'].includes(rowStatus(q).kind)||i.previewFilter==='可导入'&&rowStatus(q).kind==='ok');return `<main class="scroll">${importSteps(3)}
 <div class="tile-grid" style="margin-top:10px"><div class="stat-tile"><div class="muted small">识别题目</div><div class="stat-val">${c.all}</div></div><div class="stat-tile"><div class="muted small">可直接导入</div><div class="stat-val" style="color:#4b946e">${c.ok}</div></div><div class="stat-tile"><div class="muted small">重复 / 答案冲突</div><div class="stat-val" style="color:#b47b42">${c.duplicate+c.conflict}</div></div><div class="stat-tile"><div class="muted small">字段错误</div><div class="stat-val" style="color:#bc6061">${c.invalid}</div></div></div>
 ${title('重复题处理')}${selectField('默认冲突策略','imp_duplicateMode',['跳过重复','替换旧题','保留新旧两个版本'],i.duplicateMode,'完全重复和内容冲突会分别显示；可以逐题覆盖默认策略')}
 <div class="notice warn">${icon('warning',18)}<span>完全重复可直接跳过；答案冲突建议先打开“对比”，检查新旧答案与解析。无效题默认不导入。</span></div>
 ${title('逐题审查')}
 <div class="tabs-inline">${[['全部',c.all],['待修正',c.invalid],['重复/冲突',c.duplicate+c.conflict],['可导入',c.ok]].map(([label,count])=>`<button class="${i.previewFilter===label?'active':''}" data-action="previewFilter" data-value="${label}">${label}<span class="tag-count">${count}</span></button>`).join('')}</div>
 ${filtered.map((q,index)=>{const s=rowStatus(q),tone=s.kind==='invalid'?'err':['duplicate','conflict'].includes(s.kind)?'warn':'success';return card(`<div class="row between"><span class="muted tiny">${esc(i.sheet)} · 第 ${q.sourceRow||index+2} 行</span>${chip(s.label,tone)}</div><div class="q-text" style="margin:10px 0">${esc(q.text||'(缺少题干)')}</div><div class="chips">${chip(q.type||'未知题型')}${chip('答案 '+(q.answer||[]).join(''))}${chip(q.difficulty||'未标注')}</div>${s.kind==='invalid'?`<div class="section-caption" style="color:var(--error);margin-top:9px">${esc(s.details)}</div>`:''}${s.kind==='conflict'?`<div class="section-caption" style="color:#997245;margin-top:9px">与已有题干相同，但选项或答案存在差异</div>`:''}<div class="row between" style="margin-top:12px"><button class="link" data-action="editImportRow" data-id="${q.id}">${icon('pencil',14)} 编辑题目</button><div class="row">${['conflict','duplicate'].includes(s.kind)?`<button class="btn sm outline" data-action="compareRow" data-id="${q.id}">${icon('duplicate',14)} 对比</button>`:''}<button class="btn sm tonal" data-action="decideRow" data-id="${q.id}">处理</button></div></div>${i.decisions[q.id]?`<div class="tiny muted" style="margin-top:6px">本题策略：${esc(i.decisions[q.id])}</div>`:''}`)}).join('')||`<div class="empty-state">${illustration('empty')}<h3>此筛选下没有题目</h3><p>切换标签查看其他题目。</p></div>`}
 </main><div class="sticky-action"><button class="btn outline" data-action="back">上一步</button><button class="btn primary grow" data-action="commitImport">确认导入 ${icon('check',18)}</button></div>`}
function resultScreen(){const r=S.imports.result||{total:0,added:0,skipped:0,replaced:0,invalid:0};return `<main class="scroll"><div class="space14"></div><div class="illustration-inline">${illustration('success')}</div><div style="text-align:center;margin:4px 0 18px"><div class="page-title" style="font-size:24px">导入处理完成</div><div class="section-caption">已核对字段、答案与重复情况</div></div>${card(`<div class="row between"><div class="muted small">源文件</div><div class="semi small" style="max-width:62%;text-align:right">${esc(S.imports.name)}</div></div><div class="divider"></div><div class="tile-grid"><div class="stat-tile"><div class="muted small">新增题目</div><div class="stat-val" style="color:#4d9872">${r.added}</div></div><div class="stat-tile"><div class="muted small">覆盖更新</div><div class="stat-val">${r.replaced}</div></div><div class="stat-tile"><div class="muted small">跳过重复</div><div class="stat-val">${r.skipped}</div></div><div class="stat-tile"><div class="muted small">校验未通过</div><div class="stat-val" style="color:#b96362">${r.invalid}</div></div></div>`)}
 <div class="notice">${icon('info',18)}<span>所有变更仅写入本原型内存。刷新页面后会恢复初始演示数据。真实应用应采用事务写入和可恢复导入批次。</span></div>
 <div class="list-item" data-action="showImportReport">${icon('file',20)}<span class="grow">查看本次导入报告</span>${icon('right',16)}</div>
 <div class="space14"></div><button class="btn primary full" data-route="book_detail">打开目标题库 ${icon('right',17)}</button><div class="space8"></div><button class="btn outline full" data-action="newImport">继续导入其他文件</button></main>`}
function rawToRows(raw,map){
 const rules=S.imports.rules;
 return (raw||[]).map((r,n)=>{
  const get=k=>r?.[map[k]]??r?.[k]??'';
  let text=String(get('text')||'').trim();
  if(rules.removeSerial){try{text=text.replace(new RegExp(S.imports.customRegex),'').trim()}catch(_){/* validated before preview */}}
  let options=[];let v=get('options');
  if(Array.isArray(v))options=v.map(x=>String(x));
  else if(v&&typeof v==='object')options=Object.values(v).map(x=>String(x));
  else if(typeof v==='string'&&v.includes('|'))options=v.split('|').map(x=>x.trim());
  else options=['选项A','选项B','选项C','选项D','选项E','选项F','A','B','C','D','E','F'].map(k=>r[k]).filter(x=>x!==undefined&&x!==null&&String(x).trim()).map(x=>String(x).trim());
  if(!options.length&&rules.mergeLines){
   const lines=text.split(/\n/),kept=[];
   for(const line of lines){const match=line.match(/^\s*([A-H])[.．、:：\s]+(.+)/i);if(match)options.push(match[2].trim());else kept.push(line)}
   if(options.length)text=kept.join('\n').trim();
  }
  let answer=get('answer');
  if(Array.isArray(answer))answer=answer.map(v=>String(v).toUpperCase().trim());
  else{
   let rawAnswer=String(answer).trim().replace(/^(答案|正确答案|参考答案)\s*[:：]?/,'');
   if(rules.normalizeAnswer)rawAnswer=rawAnswer.replace(/[Ａ-Ｚａ-ｚ]/g,c=>String.fromCharCode(c.charCodeAt(0)-(c.charCodeAt(0)>65338?65248:65216))).toUpperCase();
   const sep=new RegExp(S.imports.answerDelimiter);
   answer=rawAnswer.split(sep).filter(Boolean).flatMap(a=>/^[A-H]+$/i.test(a)&&a.length>1?a.toUpperCase().split(''):[a.toUpperCase()]).map(a=>/^[1-8]$/.test(a)?'ABCDEFGH'[Number(a)-1]:a);
  }
  let type=String(get('type')||'');
  if(/不定项/.test(type))type='不定项选择题';
  else if(/多选|多项/.test(type))type='多选题';
  else if(/判断|是非/.test(type))type='判断题';
  else if(/单选|单项/.test(type))type='单选题';
  else type=rules.inferType?(answer.length>1?'多选题':'单选题'):'未知题型';
  if(type==='判断题')answer=answer.map(a=>['正确','对','√','TRUE','T'].includes(a)?'A':['错误','错','×','FALSE','F'].includes(a)?'B':a);
  let difficulty=String(get('difficulty')||'未标注');
  if(['难','较难','困难','hard','3'].includes(difficulty.toLowerCase()))difficulty='困难';
  else if(['易','简单','easy','1'].includes(difficulty.toLowerCase()))difficulty='简单';
  else if(['中','一般','普通','medium','2'].includes(difficulty.toLowerCase()))difficulty='中等';
  if(!options.length&&type==='判断题')options=['正确','错误'];
  return {id:'file'+n,text,type,options,answer,explanation:String(get('explanation')||''),difficulty,chapter:String(get('chapter')||'未分类'),sourceRow:n+Number(S.imports.startRow||2)};
 }).filter(q=>!rules.skipEmpty||q.text||q.answer.length||q.options.length)
}
function parseDelimited(txt,sep=','){let rows=[],row=[],buf='',quoted=false;txt=String(txt).replace(/^\uFEFF/,'');for(let i=0;i<txt.length;i++){let ch=txt[i];if(ch==='"'){if(quoted&&txt[i+1]==='"'){buf+='"';i++}else quoted=!quoted}else if(!quoted&&ch===sep){row.push(buf);buf=''}else if(!quoted&&(ch==='\n'||ch==='\r')){if(ch==='\r'&&txt[i+1]==='\n')i++;row.push(buf);if(row.some(v=>v.trim()))rows.push(row);row=[];buf=''}else buf+=ch}row.push(buf);if(row.some(v=>v.trim()))rows.push(row);if(!rows.length)return [];let head=rows[0].map(s=>s.trim());S.imports.columns=head;return rows.slice(1).map(parts=>Object.fromEntries(head.map((h,j)=>[h,parts[j]??''])))}
function parseTextQuestions(txt){let blocks=txt.replace(/\r/g,'').split(/\n\s*\n+/).filter(x=>x.trim());let objects=[];blocks.forEach((block,n)=>{let lines=block.split('\n').map(x=>x.trim()).filter(Boolean);let entry={题目内容:'',题目类型:'',参考答案:'',解析说明:'',难度等级:'中等',所属章节:'未分类'};const opts=[];for(let ln of lines){if(/^(?:答案|正确答案|参考答案)[:：]/.test(ln))entry.参考答案=ln.replace(/^[^:：]+[:：]/,'').trim();else if(/^(?:解析|答案解析)[:：]/.test(ln))entry.解析说明=ln.replace(/^[^:：]+[:：]/,'').trim();else if(/^[A-H][.．、:：\s]/i.test(ln)){opts.push(ln.replace(/^[A-H][.．、:：\s]+/i,''))}else if(!entry.题目内容)entry.题目内容=ln.replace(/^(?:第?\d+[.、．])\s*/,'');else entry.题目内容+=' '+ln;}entry.选项A=opts[0]||'';entry.选项B=opts[1]||'';entry.选项C=opts[2]||'';entry.选项D=opts[3]||'';objects.push(entry)});S.imports.columns=Object.keys(objects[0]||{});return objects}
function inferMap(columns){const dict={text:/题目内容|^题干$|^题目$|question|试题内容|问题/i,type:/题型|类型|type/i,options:/选项A~D|选项|options?/i,answer:/正确答案|参考答案|^答案$|answer|key/i,explanation:/解析|解释|explanation|analysis/i,difficulty:/难度|difficulty|等级/i,chapter:/章节|知识点|模块|分类|chapter/i};Object.entries(dict).forEach(([key,regex])=>{const hit=columns.find(col=>regex.test(col));S.imports.columnMap[key]=hit||'不使用'});if(columns.some(c=>/^选项A$|^A$/i.test(c)))S.imports.columnMap.options='选项A~D'}
function prepareImport(){let i=S.imports;if(i.real&&i.rawRows){i.rows=rawToRows(i.rawRows,i.columnMap)}else{i.rows=sampleRows.map(x=>({...x,options:[...x.options],answer:[...x.answer]}))}i.decisions={};i.previewFilter='全部'}
function commitImport(){const i=S.imports;let report={total:i.rows.length,added:0,replaced:0,skipped:0,invalid:0,details:[]};for(let row of i.rows){const status=rowStatus(row),policy=i.decisions[row.id]||({'跳过重复':'跳过','替换旧题':'替换旧题','保留新旧两个版本':'保留新旧两个版本'}[i.duplicateMode]||'跳过');if(status.kind==='invalid'){report.invalid++;report.details.push({q:row.text,why:status.details});continue}if(status.kind!=='ok'&&policy==='跳过'){report.skipped++;continue}const entity={...row,id:0,book:i.target,wrong:0,star:false};delete entity.sourceRow;if(status.kind!=='ok'&&policy==='替换旧题'){Object.assign(status.existing,{...entity,id:status.existing.id,book:status.existing.book,wrong:status.existing.wrong,star:status.existing.star});report.replaced++;continue}entity.id=Math.max(0,...S.questions.map(q=>q.id))+1;S.questions.push(entity);report.added++}i.result=report;S.importLog.unshift({name:i.name,added:report.added,date:'本次会话'});const b=S.books.find(b=>b.name===i.target);if(b)b.count+=report.added;go('import_result')}
function practiceConfigScreen(){return `<main class="scroll"><div class="card soft"><div class="row"><div class="support-icon" style="background:white">${icon('graduation',23)}</div><div class="grow"><div class="semi">专注练习，从现在开始</div><div class="section-caption">随时退出并保存进度</div></div></div></div>
 ${selectField('选择题库','quiz_book',S.books.map(b=>b.name),S.quiz.book)}
 ${title('选择练习模式')}<div class="tile-grid">${[['顺序练习','按原始顺序进行','list'],['随机练习','每次随机抽题','refresh'],['模拟考试','计时与统一交卷','timer'],['背题模式','即时查看标准答案','eye']].map(([name,desc,ic])=>`<button class="mini-tile" style="min-height:91px;${S.quiz.mode===name?'border:2px solid #8589d4;background:#f0f0ff':''}" data-action="quizMode" data-value="${name}"><div class="row">${icon(ic,18)}<span class="semi small">${name}</span></div><div class="tiny muted">${desc}</div></button>`).join('')}</div>
 ${title('练习范围')}<div class="tabs-inline">${['全部题目','错题','收藏'].map(s=>`<button data-action="quizRange" data-value="${s}" class="${S.quiz.range===s?'active':''}">${s}</button>`).join('')}</div>
 ${inputField('计划题数（1–100）','quiz_qty',String(S.quiz.qty),'10')}
 ${card(toggle('即时查看答案解析','模拟考试建议关闭','instant',S.settings.instant)+toggle('随机打乱选项','降低通过位置记忆答案的概率','shuffle',S.settings.shuffle))}
 <div class="space14"></div><button class="btn primary full" data-action="startQuiz">${icon('check',18)}进入练习</button></main>`}
function quizScreen(){const q=currentQ(),quiz=S.quiz,sel=quiz.selected,submitted=quiz.submitted,isCorrect=[...sel].sort().join('')===[...q.answer].sort().join('');return `<main class="scroll with-bottom">
 <div class="row between" style="margin:3px 0 10px"><div class="muted small">${quiz.index+1} / ${quiz.ids.length} 题</div><div class="row">${chip(q.type)}${chip(q.difficulty)}</div></div>${progress((quiz.index+1)/quiz.ids.length*100)}
 <div class="stage-label" style="margin-top:21px">${esc(q.chapter)}</div><div class="rich-question">${esc(q.text)}</div>
 ${q.options.map((o,i)=>{const code='ABCDEFGHIJKLMNOPQRSTUVWXYZ'[i],selected=sel.includes(code),correct=q.answer.includes(code);let klass=submitted&&correct?'correct':submitted&&selected&&!correct?'wrong':selected?'selected':'';return `<button class="option ${klass}" style="width:100%;text-align:left" data-action="selectOption" data-value="${code}"><span class="letter">${code}</span><span class="otext grow">${esc(o)}</span>${submitted&&correct?icon('check',17):submitted&&selected&&!correct?icon('close',17):selected?icon('check',17):''}</button>`}).join('')}
 ${submitted?card(`<div class="row between"><div class="lead" style="color:${isCorrect?'#41926b':'#bb6263'}">${isCorrect?'回答正确':'回答有误'}</div>${chip('标准答案 '+q.answer.join(''),isCorrect?'success':'warn')}</div><div class="section-caption" style="margin-top:9px">${esc(q.explanation)}</div><div class="row between" style="margin-top:14px"><button class="link" data-action="bookmark">${icon('bookmark',15)}${q.star?'取消收藏':'收藏此题'}</button><button class="link" data-action="askAI">${icon('spark',15)}AI 讲解</button></div>`):`<div class="notice" style="margin-top:17px">${icon('info',16)}<span>${q.type==='多选题'?'可以选择多个选项，提交后判定。':'选择最合适的答案，再点击提交。'}练习会保存所选答案。</span></div>`}
 </main><div class="sticky-action"><button class="btn outline" data-action="previousQuestion">上一题</button><button class="btn ${submitted?'secondary':'primary'} grow" data-action="${submitted?'nextQuestion':'submitAnswer'}">${submitted?(quiz.index+1===quiz.ids.length?'查看结果':'下一题'): '提交答案'} ${icon('right',16)}</button></div>`}
function quizResultScreen(){const res=S.quiz.results,correct=res.filter(x=>x.correct).length,total=S.quiz.ids.length||1,percent=Math.round(correct/total*100);return `<main class="scroll"><div class="illustration-inline" style="margin:13px auto">${illustration('success')}</div><div style="text-align:center"><div class="muted small">本次练习正确率</div><div class="result-number">${percent}<span style="font-size:23px">%</span></div><div class="muted small" style="margin:7px 0 17px">完成 ${res.length} / ${total} 题 · ${S.quiz.mode}</div></div>
 <div class="tile-grid"><div class="stat-tile"><div class="muted small">正确</div><div class="stat-val" style="color:#4e9871">${correct}</div></div><div class="stat-tile"><div class="muted small">错误</div><div class="stat-val" style="color:#b76162">${res.length-correct}</div></div></div>
 ${title('本次反馈')}${card(`<div class="section-caption">答错的题目已经记录到错题库；可通过复盘查看每道题的作答和解析。</div><div class="space14"></div><div class="chips">${chip('已自动保存记录','success')}${chip('可以再次练习')}</div>`)}
 <div class="space14"></div><button class="btn primary full" data-route="recap">${icon('list',18)}查看逐题复盘</button><div class="space8"></div><button class="btn outline full" data-route="practice_config">再练一组</button></main>`}
function recapScreen(){return `<main class="scroll">${S.quiz.ids.map((id,i)=>{let q=S.questions.find(x=>x.id===id),a=S.quiz.results.find(r=>r.id===id);return card(`<div class="row between"><span class="muted tiny">第 ${i+1} 题 · ${q.type}</span>${chip(a?a.correct?'正确':'错误':'未完成',a?.correct?'success':a?'err':'')}</div><div class="q-text" style="margin:10px 0">${esc(q.text)}</div><div class="small">我的答案：<b>${esc(a?.selected?.join('')||'未作答')}</b>　标准答案：<b>${q.answer.join('')}</b></div><div class="section-caption" style="margin-top:9px">${esc(q.explanation)}</div>`)}).join('')}</main>`}
function historyScreen(){return `<main class="scroll"><div class="notice">${icon('clock',18)}<span>显示最近完成或中断的练习。正式版可恢复中断的答题会话。</span></div>${S.history.map((h,i)=>card(`<div class="row"><div class="support-icon">${icon('graduation',21)}</div><div class="grow"><div class="semi small">${esc(h.title)}</div><div class="tiny muted" style="margin-top:5px">${h.date} · ${h.qty} 题</div></div><div style="font-size:19px;font-weight:800;color:var(--primary2)">${h.score}%</div></div><div class="row between" style="margin-top:10px"><span class="tiny muted">记录 ${S.history.length-i}</span><button class="link" data-route="stats">学习分析 ${icon('right',12)}</button></div>`)).join('')}</main>`}
function planScreen(){return `<main class="scroll"><div class="hero" style="min-height:134px"><div class="hero-text"><div class="eyebrow">DAILY ROUTINE</div><h2 style="font-size:19px">学习是一点点<br>积累的事。</h2><p>适合自己的节奏最重要</p></div><div style="position:absolute;right:-25px;top:16px;transform:scale(.7)">${illustration('empty')}</div></div>
 ${title('每日目标')}${card(`<div class="row between"><span class="semi">每日练习题数</span><span class="lead">${S.planTarget} 题</span></div><input type="range" style="width:100%;accent-color:#686fc8;margin:18px 0 7px" min="5" max="100" step="5" value="${S.planTarget}" data-bind="plan_target"/><div class="row between tiny muted"><span>5 题 · 轻量</span><span>100 题 · 强化</span></div>`)}
 ${title('复习原则')}${card(`<div class="semi">错题复习周期</div><p class="section-caption">依据错误次数和近期掌握情况安排复习。默认使用保守的可解释规则，避免做对一次就移出错题库。</p><div class="chips">${chip('新错题：次日','on')}${chip('连续正确：逐步延长')}${chip('可手动标记掌握')}</div>`)}
 ${title('提醒设置')}${card(toggle('每日复习提醒','仅在授予 Android 通知权限后显示','dailyReminder',S.settings.dailyReminder))}</main>`}
function settingsScreen(){return `<main class="scroll"><div class="section-head"><h2>外观与阅读</h2></div><div class="card">${toggle('跟随系统动态配色','正式版调用 Android Material You 动态取色','dynamic',S.settings.dynamic)}${toggle('深色模式预览','在此原型中切换深色配色','dark',S.settings.dark)}</div>
 ${title('答题习惯')}${card(toggle('即时显示答案解析','普通练习提交后立即展示解析','instant',S.settings.instant)+toggle('随机排列选项','进入下一次练习时启用','shuffle',S.settings.shuffle)+toggle('触感反馈','正式版使用系统触觉反馈 API','vibrate',S.settings.vibrate)+toggle('回答后自动下一题','不建议默认打开','autoNext',S.settings.autoNext))}
 ${title('数据与服务')}<div class="list-simple"><div class="list-item" data-route="audit">${icon('duplicate',19)}<span class="grow">题库体检与重复题审查</span>${icon('right',17)}</div><div class="list-item" data-route="data">${icon('download',19)}<span class="grow">备份、恢复、导出</span>${icon('right',17)}</div><div class="list-item" data-route="ai">${icon('spark',19)}<span class="grow">可选 AI 服务</span>${icon('right',17)}</div><div class="list-item" data-route="review_plan">${icon('bell',19)}<span class="grow">复习计划及提醒</span>${icon('right',17)}</div></div><div class="section-caption" style="text-align:center;margin:22px 0">知序 · Material 3 原型 · 0.1.0 Preview</div></main>`}
function dataScreen(){return `<main class="scroll"><div class="card soft"><div class="row"><div class="support-icon" style="background:white">${icon('lock',23)}</div><div class="grow"><div class="semi">本地优先 · 数据属于你</div><div class="section-caption">正式版默认无需账号，不将题库上传到云端</div></div></div></div>
 ${title('备份与迁移')}
 <div class="list-simple"><div class="list-item" data-action="downloadJson">${icon('download',19)}<div class="grow"><div class="semi small">导出题目 JSON</div><div class="tiny muted">本原型可下载当前演示题目</div></div>${icon('right',17)}</div><div class="list-item" data-action="showZipExplain">${icon('duplicate',19)}<div class="grow"><div class="semi small">完整 ZIP 备份</div><div class="tiny muted">正式版包含题目、媒体、学习记录、规则</div></div>${icon('right',17)}</div><div class="list-item" data-action="showZipExplain">${icon('upload',19)}<div class="grow"><div class="semi small">从备份恢复</div><div class="tiny muted">正式版支持版本检查及事务恢复</div></div>${icon('right',17)}</div></div>
 ${title('数据检查')}${card(`<div class="row between"><span class="small">已加载演示题目</span><b>${S.questions.length}</b></div><div class="divider"></div><div class="row between"><span class="small">题库</span><b>${S.books.length}</b></div><div class="divider"></div><div class="row between"><span class="small">已保存的导入规则预设</span><b>${S.imports.presets.length}</b></div>`)}
 <div class="list-item section-space" data-route="audit">${icon('duplicate',19)}<span class="grow">全库重复题审查</span>${icon('right',17)}</div><div class="notice warn">${icon('warning',18)}<span>浏览器预览不会永久保存修改。Android 正式版将采用 Room 数据库和版本化迁移。</span></div></main>`}
function aiScreen(){return `<main class="scroll"><div class="card soft"><div class="row start"><div class="support-icon" style="background:white">${icon('spark',25)}</div><div class="grow"><div class="lead">AI 是可选增强功能</div><div class="section-caption" style="margin-top:5px">不连接服务也可以使用全部基础刷题和本地导入功能。</div></div></div></div>
 ${title('模型连接')}${selectField('接口协议','ai_protocol',['OpenAI 兼容','Google Gemini 原生','其他自定义协议（预留）'],'OpenAI 兼容')}
 ${inputField('Base URL','ai_url','https://api.example.com/v1','https://...')}${inputField('模型名称','ai_model','my-model','例如模型标识')}
 <div class="field"><label>API Key</label><input type="password" placeholder="仅在本地配置，原型不保存密钥"/></div>
 <div class="notice warn">${icon('lock',18)}<span>这是 UI 示意，不会发起任何网络请求。正式版使用 Android Keystore 保护敏感配置，并在每次上传题目内容前明确告知。</span></div>
 ${title('可选智能能力')}<div class="list-simple">${[['spark','辅助补充答案解析'],['warning','检查疑似错误答案'],['layers','识别复杂表格结构'],['review','知识点问答']].map(([ic,label])=>`<div class="list-item">${icon(ic,20)}<div class="grow">${label}</div>${chip('需主动启用')}</div>`).join('')}</div>
 <div class="space14"></div><button class="btn outline full" data-action="testAI">${icon('cloud',18)}测试连接（原型占位）</button></main>`}
function duplicateGroups(){const by=new Map();for(const q of S.questions){const key=normalizedText(q.text);if(!by.has(key))by.set(key,[]);by.get(key).push(q)}return [...by.entries()].filter(([key,items])=>key&&items.length>1).map(([key,items])=>({key,items,conflict:items.some(x=>[...x.answer].sort().join('')!==[...items[0].answer].sort().join(''))}))}
function auditScreen(){const all=duplicateGroups(),open=all.filter(g=>!S.auditIgnored.includes(g.key));const withConflicts=open.filter(x=>x.conflict).length,missing=S.questions.filter(q=>!q.explanation).length;
 return `<main class="scroll"><div class="card soft"><div class="row start"><div class="support-icon">${icon('duplicate',23)}</div><div class="grow"><div class="lead">全库题目体检</div><div class="section-caption" style="margin-top:5px">查找题干重复、答案冲突和缺失解析。跨题库同题只提醒，不自动删除。</div></div></div></div>
 <div class="tile-grid section-space"><div class="stat-tile"><div class="small muted">共计题目</div><div class="stat-val">${S.questions.length}</div></div><div class="stat-tile"><div class="small muted">待审查重复组</div><div class="stat-val" style="color:#ae7a42">${open.length}</div></div><div class="stat-tile"><div class="small muted">答案冲突组</div><div class="stat-val" style="color:#b86665">${withConflicts}</div></div><div class="stat-tile"><div class="small muted">缺少解析</div><div class="stat-val">${missing}</div></div></div>
 ${title('检测规则')}<div class="chips">${chip('规范化题干')}${chip('跨题库比较')}${chip('答案差异')}${chip('无损审查')}</div>
 ${title('待处理列表')}${open.map((group,i)=>card(`<div class="row between"><div class="semi small">重复组 ${i+1}</div>${chip(group.conflict?'答案冲突':'内容相同',group.conflict?'err':'warn')}</div><div class="q-text" style="margin:9px 0">${esc(group.items[0].text)}</div><div class="section-caption">涉及 ${group.items.length} 道题 · ${[...new Set(group.items.map(x=>x.book))].map(esc).join(' / ')}</div><button class="btn tonal full sm" style="margin-top:13px" data-action="auditCompare" data-value="${esc(group.key)}">逐题对比并处理 ${icon('right',15)}</button>`)).join('')||`<div class="empty-state">${illustration('success')}<h3>当前没有待处理的重复题</h3><p>审查记录会在本次演示中保留。</p></div>`}
 ${title('文件级重复检查')}${card(`<div class="section-caption">导入同名文件、相同来源或修订版本时，不应直接合并：需要再次比较题目内容和答案版本。</div><div class="space8"></div>${S.importLog.length?S.importLog.map(l=>`<div class="nav-list-item"><div class="grow small">${esc(l.name)}<div class="tiny muted">${l.added} 条新增 · ${l.date}</div></div>${chip('已审查','success')}</div>`).join(''):'<div class="tiny muted">当前尚无本次会话的导入记录。</div>'}`)}
 </main>`}
function uiForScreen(){switch(S.screen){case 'home':return homeScreen();case 'library':return libraryScreen();case 'review':return reviewScreen();case 'stats':return statsScreen();case 'book_detail':return bookDetailScreen();case 'questions':return questionsScreen();case 'editor':return editorScreen();case 'import_source':return sourceScreen();case 'import_mapping':return mappingScreen();case 'import_preview':return previewScreen();case 'import_result':return resultScreen();case 'practice_config':return practiceConfigScreen();case 'quiz':return quizScreen();case 'quiz_result':return quizResultScreen();case 'recap':return recapScreen();case 'history':return historyScreen();case 'review_plan':return planScreen();case 'settings':return settingsScreen();case 'data':return dataScreen();case 'audit':return auditScreen();case 'ai':return aiScreen();default:return homeScreen()}}
function modalHtml(){const m=S.modal;if(!m)return '';let content='';let head='';if(m.kind==='compare'){const row=S.imports.rows.find(x=>x.id===m.id),old=rowStatus(row).existing;head='重复题差异对比';content=`<div class="section-caption">按照题干定位到现有题目，请核对选项、答案及解析。</div><div class="space8"></div><div class="card"><b class="small">已有题目</b><div class="q-text" style="margin:8px 0">${esc(old?.text||'未找到')}</div><div class="small">答案：<b>${old?.answer?.join('')||'-'}</b></div><div class="section-caption">${esc(old?.explanation||'')}</div></div><div class="space8"></div><div class="card soft"><b class="small">准备导入</b><div class="q-text" style="margin:8px 0">${esc(row.text)}</div><div class="small">答案：<b>${row.answer.join('')}</b></div><div class="section-caption">${esc(row.explanation)}</div></div><div class="space8"></div>${['跳过','替换旧题','保留新旧两个版本'].map(t=>`<button style="margin:4px 0" class="btn ${S.imports.decisions[m.id]===t?'primary':'outline'} full sm" data-action="chooseResolution" data-id="${m.id}" data-value="${t}">${t}</button>`).join('')}`;}
 if(m.kind==='decide'){const row=S.imports.rows.find(x=>x.id===m.id),st=rowStatus(row);head='选择本题处理方式';content=`<div class="q-text">${esc(row.text)}</div><div class="notice ${st.kind==='invalid'?'err':'warn'}">${icon('info',16)}<span>${st.kind==='invalid'?'本题存在校验错误。修正答案后才能导入。':'当前处理策略只作用于这一道题。'}</span></div>${st.kind==='invalid'?`<button class="btn primary full" data-action="editImportRow" data-id="${m.id}">编辑并修正题目</button>`:['跳过','替换旧题','保留新旧两个版本'].map(t=>`<button style="margin:5px 0" class="btn ${S.imports.decisions[m.id]===t?'primary':'outline'} full" data-action="chooseResolution" data-id="${m.id}" data-value="${t}">${t}</button>`).join('')}`;}
 if(m.kind==='editRow'){const r=S.imports.rows.find(x=>x.id===m.id);head='审查并修改题目';content=`<div class="section-caption">来源：工作表 ${esc(S.imports.sheet)} · 第 ${r.sourceRow||'-'} 行，修改只作用于本次导入预览。</div><div class="field"><label>题干</label><textarea id="m_text">${esc(r.text)}</textarea></div><div class="value-row"><div class="field"><label>题型</label><select id="m_type">${['单选题','多选题','判断题','不定项选择题'].map(t=>`<option ${r.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>难度</label><select id="m_difficulty">${['简单','中等','困难','未标注'].map(t=>`<option ${r.difficulty===t?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="field"><label>选项（每行一个）</label><textarea id="m_options" rows="4">${esc(r.options.join('\n'))}</textarea></div><div class="field"><label>标准答案（例如 A,B）</label><input id="m_answer" value="${esc(r.answer.join(','))}"/></div><div class="field"><label>解析</label><textarea id="m_explanation">${esc(r.explanation)}</textarea></div><div class="field"><label>章节</label><input id="m_chapter" value="${esc(r.chapter)}"/></div><button class="btn primary full" data-action="saveRow">保存并重新校验</button>`;}
 if(m.kind==='savePreset'){head='保存自定义规则';content=`<div class="section-caption">保存当前识别规则和字段映射，后续导入相同结构可以快速复用。</div>${inputField('规则名称','m_presetName','我的铁路题库规则','例如：某某单位 Excel 题库')}<button class="btn primary full" data-action="confirmPreset">保存规则预设</button>`;}
 if(m.kind==='paste'){head='粘贴文本题库';content=`<div class="section-caption">示例：题干占一行，A/B/C/D 分行，最后填写“答案：A”和“解析：...”。题目之间留空行。</div><div class="field"><textarea id="m_pasted" rows="9" placeholder="1. 下列哪项属于列车运行图内容？\nA. 列车运行时刻\nB. 铁路票价\n答案：A\n解析：运行图规定列车时刻。"></textarea></div><button class="btn primary full" data-action="confirmPaste">使用粘贴内容</button>`;}
 if(m.kind==='newBook'){head='新建题库';content=`${inputField('题库名称','m_bookName','新导入题库','例如：铁路校招 2027')}<button class="btn primary full" data-action="confirmBook">创建题库并设为导入目标</button>`;}
 if(m.kind==='answerSheet'){head='答题卡';content=`<div class="section-caption">点击题号跳转；深色题号表示已提交，边框表示当前题。</div><div class="tile-grid" style="grid-template-columns:repeat(5,1fr);margin-top:12px">${S.quiz.ids.map((id,j)=>`<button class="btn sm ${j===S.quiz.index?'primary':S.quiz.results.some(r=>r.id===id)?'tonal':'outline'}" style="padding:7px 0" data-action="jumpQuestion" data-index="${j}">${j+1}</button>`).join('')}</div><button class="btn outline full" style="margin-top:13px" data-action="finishQuiz">结束本次练习</button>`;}
 if(m.kind==='renameBook'){head='题库管理';content=`${inputField('题库名称','m_renameBook',S.activeBook,'')}${selectField('操作','m_bookAction',['重命名','导出 JSON','取消'],'重命名')}<button class="btn primary full" data-action="manageBook">确认</button>`;}
 if(m.kind==='importReport'){head='导入报告';let r=S.imports.result;content=`<div class="section-caption">原始文件：${esc(S.imports.name)}</div><div class="space8"></div>${card(`<div class="row between"><span>新增</span><b>${r.added}</b></div><div class="divider"></div><div class="row between"><span>更新</span><b>${r.replaced}</b></div><div class="divider"></div><div class="row between"><span>跳过</span><b>${r.skipped}</b></div><div class="divider"></div><div class="row between"><span>无效</span><b>${r.invalid}</b></div>`)}<div class="space8"></div>${r.details?.map(x=>`<div class="notice err">${icon('warning',17)}<div>${esc(x.q)}<br><b>${esc(x.why)}</b></div></div>`).join('')||'<div class="section-caption">没有异常行。</div>'}`;}
 if(m.kind==='auditCompare'){const group=duplicateGroups().find(g=>g.key===m.key);head='全库重复题对比';content=`<div class="section-caption">同一题干出现在不同题库并不一定是错误。建议先检查标准答案，再决定是否忽略重复提醒。</div>${group?.items.map(q=>`<div class="card" style="margin-top:10px"><div class="row between"><b class="small">${esc(q.book)}</b>${chip('ID '+q.id)}</div><div class="q-text" style="margin:9px 0">${esc(q.text)}</div><div class="small">标准答案：<b>${q.answer.join('')}</b></div><div class="section-caption">${esc(q.explanation)}</div></div>`).join('')||''}<div class="space14"></div><button class="btn primary full" data-action="ignoreAuditGroup" data-key="${esc(m.key)}">已核对，暂不再提示</button><div class="section-caption" style="margin-top:9px">本原型仅标记已审查，不直接删除题目或学习记录。</div>`;}
 if(m.kind==='info'){head=m.title||'说明';content=`<div class="section-caption" style="font-size:13px">${esc(m.text)}</div><button class="btn primary full" style="margin-top:20px" data-action="closeModal">知道了</button>`;}
 return `<div class="sheet-mask" data-action="maskClose"><div class="sheet" role="dialog" aria-modal="true" aria-label="${esc(head)}" ><div class="sheet-handle"></div><div class="row between"><h3 class="sheet-title">${esc(head)}</h3><button class="icon-btn" data-action="closeModal" aria-label="关闭">${icon('close',18)}</button></div>${content}</div></div>`;
}
function renderSide(){const side=$('#sidePanel');if(!side)return;side.innerHTML=`<div class="side-logo">知序 <small>Android · Material 3 产品原型</small></div>${screenCatalog.map(g=>`<div class="side-group">${g.group}</div>${g.items.map(([id,label],i)=>`<button class="side-link ${S.screen===id?'active':''}" data-route="${id}">${icon(['home','books','review','chart','file','list','pencil','upload'][i%8],15)}<span>${label}</span><span>${String([...screenCatalog].flatMap(x=>x.items).findIndex(x=>x[0]===id)+1).padStart(2,'0')}</span></button>`).join('')}`).join('')}`}
function toast(msg){S.toast=msg;render();setTimeout(()=>{if(S.toast===msg){S.toast='';const el=$('.toast');if(el)el.remove()}},2400)}
function render(){document.documentElement.dataset.theme=S.settings.dark?'dark':'light';document.body.classList.toggle('dark-mode',!!S.settings.dark);const app=$('#app');app.innerHTML=header()+uiForScreen()+modalHtml()+(S.toast?`<div class="toast" role="status" style="position:absolute;left:12%;right:12%;bottom:90px;padding:13px 18px;border-radius:13px;background:#30344d;color:white;text-align:center;font-size:12px;z-index:10;box-shadow:0 8px 20px #0003">${esc(S.toast)}</div>`:'');renderSide();}
function finishQuiz(){const q=S.quiz;for(let id of q.ids){if(!q.results.some(r=>r.id===id))q.results.push({id,selected:[],correct:false})}const correct=q.results.filter(r=>r.correct).length;S.history.unshift({title:`${q.book} · ${q.mode}`,date:'刚刚',score:Math.round(correct/q.ids.length*100),qty:q.ids.length});S.modal=null;go('quiz_result')}
function updateRowFromSheet(){const m=S.modal,r=S.imports.rows.find(q=>q.id===m.id);if(!r)return;const val=id=>document.getElementById(id)?.value??'';r.text=val('m_text').trim();r.type=val('m_type');r.difficulty=val('m_difficulty');r.options=val('m_options').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);r.answer=val('m_answer').toUpperCase().split(/[^A-Z]+/).filter(Boolean).flatMap(x=>x.length>1?x.split(''):[x]);r.explanation=val('m_explanation');r.chapter=val('m_chapter');S.modal=null;toast('已保存修改，校验结果已更新')}
function getEditValue(key){const el=document.querySelector(`[data-bind="${key}"]`);return el?.value??S.form?.[key]??''}
function manageAction(action,el){switch(action){
 case 'back':back();break;case 'closeModal':case 'maskClose':S.modal=null;render();break;
 case 'libraryMenu':S.modal={kind:'info',title:'题库管理',text:'可以进入某个题库查看题目、编辑、导入、导出或重命名。批量删除需再次确认。'};render();break;
 case 'openBook':S.activeBook=el.dataset.name;S.quiz.book=S.activeBook;S.search='';go('book_detail');break;
 case 'chapter':S.filter='全部';S.search=el.dataset.chapter;go('questions');break;
 case 'bookMenu':S.modal={kind:'renameBook'};render();break;
 case 'manageBook':{const name=$('#m_renameBook')?.value.trim(),op=$('#m_bookAction')?.value;if(op==='重命名'&&name){const book=S.books.find(b=>b.name===S.activeBook);if(book)book.name=name;S.questions.forEach(q=>{if(q.book===S.activeBook)q.book=name});S.activeBook=name;S.quiz.book=name;S.modal=null;toast('已重命名题库')}else if(op==='导出 JSON'){S.modal=null;downloadJson()}else{S.modal=null;render()}break;}
 case 'searchBooks':S.search=$('#bookSearch')?.value.trim()||'';render();break;
 case 'searchQuestions':S.search=$('#questionSearch')?.value.trim()||'';render();break;
 case 'filterQuestions':S.filter=el.dataset.value;render();break;
 case 'addQuestion':S.editId=null;S.form={};go('editor');break;
 case 'editQuestion':S.editId=Number(el.dataset.id);S.form={};go('editor');break;
 case 'saveQuestion':{const text=getEditValue('edit_text').trim(),ans=getEditValue('edit_answer').toUpperCase().split(/[^A-Z]+/).filter(Boolean).flatMap(x=>x.length>1?x.split(''):[x]);const options=[0,1,2,3].map(i=>getEditValue('edit_opt'+i)).filter(x=>x.trim());if(!text||!ans.length||!options.length){toast('请填写题干、选项和答案');break}if(ans.some(x=>x.charCodeAt(0)-65>=options.length)){toast('答案指向了不存在的选项');break}let q=S.editId?S.questions.find(q=>q.id===S.editId):null;let updated={text,options,answer:ans,type:getEditValue('edit_type'),difficulty:getEditValue('edit_difficulty'),explanation:getEditValue('edit_explanation'),chapter:getEditValue('edit_chapter')||'未分类'};if(q)Object.assign(q,updated);else {S.questions.push({...updated,id:Math.max(0,...S.questions.map(x=>x.id))+1,book:S.activeBook,wrong:0,star:false});const book=S.books.find(b=>b.name===S.activeBook);if(book)book.count++}S.screen='questions';S.stack=[];toast('题目已保存');break}
 case 'reviewTab':S.reviewTab=el.dataset.value;render();break;
 case 'practiceOne':S.quiz.book=S.questions.find(q=>q.id===Number(el.dataset.id))?.book||S.activeBook;S.quiz.ids=[Number(el.dataset.id)];S.quiz.index=0;S.quiz.selected=[];S.quiz.submitted=false;S.quiz.results=[];go('quiz');break;
 case 'startReview':{let q=S.questions.filter(x=>x.wrong>0);S.quiz.ids=q.map(x=>x.id);S.quiz.index=0;S.quiz.selected=[];S.quiz.submitted=false;S.quiz.results=[];S.quiz.mode='错题复习';go('quiz');break}
 case 'statsRange':S.tabStat=el.dataset.value;render();break;
 case 'quizMode':S.quiz.mode=el.dataset.value;render();break;
 case 'quizRange':S.quiz.range=el.dataset.value;render();break;
 case 'startQuiz':{const qty=Number(S.quiz.qty);if(!Number.isFinite(qty)||qty<1||qty>100){toast('练习题数应在 1 到 100 之间');break}initQuiz();break}
 case 'selectOption':{if(S.quiz.submitted)break;let q=currentQ(),v=el.dataset.value;if(['单选题','判断题'].includes(q.type)){S.quiz.selected=[v]}else S.quiz.selected=S.quiz.selected.includes(v)?S.quiz.selected.filter(x=>x!==v):[...S.quiz.selected,v];render();break}
 case 'submitAnswer':{if(!S.quiz.selected.length){toast('请先选择答案');break}const q=currentQ();S.quiz.submitted=true;const correct=[...S.quiz.selected].sort().join('')===[...q.answer].sort().join('');if(!correct)q.wrong=(q.wrong||0)+1;S.quiz.results=S.quiz.results.filter(x=>x.id!==q.id);S.quiz.results.push({id:q.id,selected:[...S.quiz.selected],correct});render();break}
 case 'nextQuestion':if(S.quiz.index+1>=S.quiz.ids.length)finishQuiz();else{S.quiz.index++;let old=S.quiz.results.find(r=>r.id===S.quiz.ids[S.quiz.index]);S.quiz.selected=old?[...old.selected]:[];S.quiz.submitted=!!old;render()}break;
 case 'previousQuestion':if(S.quiz.index===0){toast('已经是第一题');break}S.quiz.index--;{const old=S.quiz.results.find(r=>r.id===S.quiz.ids[S.quiz.index]);S.quiz.selected=old?[...old.selected]:[];S.quiz.submitted=!!old;}render();break;
 case 'answerSheet':S.modal={kind:'answerSheet'};render();break;
 case 'jumpQuestion':{S.quiz.index=Number(el.dataset.index);let old=S.quiz.results.find(r=>r.id===S.quiz.ids[S.quiz.index]);S.quiz.selected=old?[...old.selected]:[];S.quiz.submitted=!!old;S.modal=null;render();break}
 case 'finishQuiz':finishQuiz();break;
 case 'bookmark':{const q=currentQ();q.star=!q.star;toast(q.star?'已加入收藏':'已取消收藏');break}
 case 'askAI':S.modal={kind:'info',title:'AI 解析',text:'该功能将在 Android 正式版通过用户配置的服务商连接实现。当前原型不调用网络，也不会上传题干。'};render();break;
 case 'toggle':{let key=el.dataset.key;S.settings[key]=!S.settings[key];render();break}
 case 'toggleImportRule':{let key=el.dataset.key;S.imports.rules[key]=!S.imports.rules[key];render();break}
 case 'pickFile':$('#fileChooser')?.click();break;
 case 'useDemo':{let i=S.imports;i.name='2026铁路运输模拟题.xlsx';i.kind='演示 Excel';i.fromFile=false;i.real=false;i.rawRows=null;i.columns=[];i.rows=[];toast('已选用 8 行示例 Excel 题目');break}
 case 'pasteText':S.modal={kind:'paste'};render();break;
 case 'confirmPaste':{let v=$('#m_pasted')?.value||'';if(!v.trim()){toast('请输入题目文本');break}const raw=parseTextQuestions(v);S.imports.name='粘贴文本题库.txt';S.imports.kind='TXT';S.imports.rawRows=raw;S.imports.real=true;S.imports.fromFile=true;inferMap(S.imports.columns||[]);S.modal=null;toast(`已读取 ${raw.length} 道候选题`);break}
 case 'startImport':{if(S.imports.target==='新建题库…'){S.modal={kind:'newBook'};render();break}go('import_mapping');break}
 case 'confirmBook':{const name=$('#m_bookName')?.value.trim();if(!name){toast('请输入题库名称');break}if(!S.books.some(b=>b.name===name))S.books.push({name,desc:'用户导入 · 自定义题库',count:0,completed:0,color:'lilac'});S.imports.target=name;S.activeBook=name;S.quiz.book=name;S.modal=null;go('import_mapping');break}
 case 'savePreset':S.modal={kind:'savePreset'};render();break;
 case 'confirmPreset':{const name=$('#m_presetName')?.value.trim();if(!name){toast('请填写规则名称');break}const i=S.imports;if(!i.presets.includes(name))i.presets.push(name);i.preset=name;i.savedPresets ||= {};i.savedPresets[name]={rules:{...i.rules},columnMap:{...i.columnMap},customRegex:i.customRegex,answerDelimiter:i.answerDelimiter};S.modal=null;toast('规则预设已保存（本次演示会话）');break}
 case 'buildPreview':{try{new RegExp(S.imports.customRegex);new RegExp(S.imports.answerDelimiter)}catch(e){toast('自定义规则不是有效的正则表达式');break}prepareImport();go('import_preview');break}
 case 'previewFilter':S.imports.previewFilter=el.dataset.value;render();break;
 case 'editImportRow':S.modal={kind:'editRow',id:el.dataset.id};render();break;
 case 'compareRow':S.modal={kind:'compare',id:el.dataset.id};render();break;
 case 'decideRow':S.modal={kind:'decide',id:el.dataset.id};render();break;
 case 'chooseResolution':S.imports.decisions[el.dataset.id]=el.dataset.value;S.modal=null;toast('本题处理策略已更新');break;
 case 'saveRow':updateRowFromSheet();break;
 case 'commitImport':commitImport();break;
 case 'showImportReport':S.modal={kind:'importReport'};render();break;
 case 'newImport':S.imports.rows=[];S.imports.result=null;S.imports.fromFile=false;S.imports.real=false;go('import_source');break;
 case 'downloadJson':downloadJson();break;
 case 'showZipExplain':S.modal={kind:'info',title:'完整备份 · 设计说明',text:'正式版会生成包含题库数据库、插图、答题记录、规则预设和版本清单的 ZIP 包，并校验恢复过程。本 HTML 原型仅提供当前题目 JSON 导出。'};render();break;
 case 'auditCompare':S.modal={kind:'auditCompare',key:el.dataset.value};render();break;
 case 'ignoreAuditGroup':S.auditIgnored.push(el.dataset.key);S.modal=null;toast('已标记审查完成，未修改题目数据');break;
 case 'testAI':S.modal={kind:'info',title:'连接测试',text:'演示原型不会读取真实 API Key 或发起网络调用。Android 正式版将进行协议校验、请求超时与错误提示。'};render();break;
 default:break;
 }}
function downloadJson(){const data=JSON.stringify({format:'zhixu-quiz-preview',version:1,questions:S.questions},null,2),url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='知序_演示题库.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('已生成 JSON 导出文件')}
$('#app').addEventListener('click',e=>{const target=e.target.closest('[data-route],[data-action]');if(!target)return;const route=target.dataset.route,action=target.dataset.action;if(route){if(target.dataset.reset)go(route,true);else go(route);return}if(action==='maskClose'&&e.target!==target)return;if(action==='toggle'&&target.dataset.key&&S.screen==='import_mapping')manageAction('toggleImportRule',target);else manageAction(action,target)});
$('#sidePanel').addEventListener('click',e=>{let item=e.target.closest('[data-route]');if(item)go(item.dataset.route)});
$('#app').addEventListener('change',async e=>{const el=e.target;
 if(el.id==='fileChooser'&&el.files?.[0]){const file=el.files[0],name=file.name,ext=name.split('.').pop().toLowerCase(),i=S.imports;i.name=name;i.kind=ext.toUpperCase();i.fromFile=true;i.rawRows=null;i.real=false;i.columns=[];if(['csv','tsv','txt','json'].includes(ext)){try{const txt=await file.text();if(ext==='csv'||ext==='tsv')i.rawRows=parseDelimited(txt,ext==='csv'?',':'\t');if(ext==='json'){let val=JSON.parse(txt);if(!Array.isArray(val))val=val.questions||val.items||val.data||[];if(!Array.isArray(val))throw Error('JSON 需要数组或 questions/items/data 数组');i.rawRows=val;i.columns=Object.keys(val[0]||{})}if(ext==='txt')i.rawRows=parseTextQuestions(txt);i.real=true;inferMap(i.columns)}catch(err){i.rawRows=null;i.real=false;toast('文件解析失败：'+String(err.message).slice(0,75));return}}toast(i.real?`已读取 ${i.rawRows.length} 行候选数据`:`${ext.toUpperCase()} 将使用示例题演示识别流程`);return}
 if(el.dataset.bind){const key=el.dataset.bind,v=el.value,i=S.imports;if(key.startsWith('column_')){i.columnMap[key.slice(7)]=v;return}if(key.startsWith('imp_')){const map={imp_target:'target',imp_sheet:'sheet',imp_startRow:'startRow',imp_customRegex:'customRegex',imp_answerDelimiter:'answerDelimiter',imp_duplicateMode:'duplicateMode',imp_preset:'preset'};i[map[key]]=v;if(key==='imp_preset'&&i.savedPresets?.[v]){let saved=i.savedPresets[v];Object.assign(i,{rules:{...saved.rules},columnMap:{...saved.columnMap},customRegex:saved.customRegex,answerDelimiter:saved.answerDelimiter});render()}return}if(key==='quiz_book')S.quiz.book=v;else if(key==='quiz_qty')S.quiz.qty=Number(v);else if(key==='plan_target'){S.planTarget=Number(v);render()}else{S.form ||= {};S.form[key]=v;}}});
$('#app').addEventListener('input',e=>{const el=e.target;if(el.matches('[data-bind]')){const k=el.dataset.bind;if(k==='plan_target'){S.planTarget=Number(el.value);const t=el.closest('.card')?.querySelector('.lead');if(t)t.textContent=`${S.planTarget} 题`;}else if(!k.startsWith('imp_')&&!k.startsWith('column_')){S.form ||= {};S.form[k]=el.value}}});
render();
